import { act } from "react";
import { userEvent } from "@testing-library/user-event";
import { enUS, enGB } from "date-fns/locale";
import React, { useState } from "react";
import { OUTSIDE_CLICK_IGNORE_CLASS } from "../calendar";

import {
  KeyType,
  addDays,
  addMonths,
  addWeeks,
  addYears,
  formatDate,
  getDay,
  getEndOfWeek,
  getHours,
  getMinutes,
  getSeconds,
  getStartOfWeek,
  isSameDay,
  newDate,
  safeDateFormat,
  subDays,
  subMonths,
  subWeeks,
  subYears,
} from "../date_utils";
import DatePicker, {
  registerLocale,
  setDefaultLocale,
  getDefaultLocale,
} from "../index";

import CustomInput from "./helper_components/custom_input";
import ShadowRoot from "./helper_components/shadow_root";
import TestWrapper from "./helper_components/test_wrapper";
import {
  getKey,
  safeQuerySelector,
  setupMockResizeObserver,
} from "./test_utils";

const renderDatePickerWithRef = (
  props: React.ComponentProps<typeof DatePicker>,
) => {
  let instance: DatePicker | null = null;
  const result = render(
    <DatePicker
      ref={(node) => {
        instance = node;
      }}
      {...props}
    />,
  );

  return { ...result, instance: instance as DatePicker | null };
};

function getSelectedDayNode(container: HTMLElement) {
  return (
    container.querySelector('.react-datepicker__day[tabindex="0"]') ?? undefined
  );
}

function findSelectedDay(container: HTMLElement, targetDate: Date) {
  const days = Array.from<HTMLElement>(
    container.querySelectorAll(".react-datepicker__day"),
  );
  return days.find(
    (d) =>
      d.getAttribute("aria-label") ===
      `Choose ${formatDate(targetDate, "PPPP")}`,
  );
}

function goToLastMonth(container: HTMLElement) {
  const lastMonthButton = container.querySelector(
    ".react-datepicker__navigation-icon--previous",
  );
  expect(lastMonthButton).toBeTruthy();
  fireEvent.click(lastMonthButton!);
}

function goToNextMonth(container: HTMLElement) {
  const nextMonthButton = safeQuerySelector(
    container,
    ".react-datepicker__navigation-icon--next",
  );
  fireEvent.click(nextMonthButton!);
}

function formatDayWithZeros(day: number) {
  const dayString = day.toString();

  if (dayString.length === 1) {
    return `00${dayString}`;
  }
  if (dayString.length === 2) {
    return `0${dayString}`;
  }
  return dayString;
}

const hideDocument = (calendarInput: HTMLElement) => {
  jest.spyOn(document, "visibilityState", "get").mockReturnValue("hidden");
  fireEvent(document, new Event("visibilitychange"));
  // Blur, To simulate the browser auto-blur the input before document hide
  fireEvent.blur(calendarInput);
};

const showDocument = (calendarInput: HTMLElement) => {
  jest.spyOn(document, "visibilityState", "get").mockReturnValue("visible");
  fireEvent(document, new Event("visibilitychange"));
  // Focus, To simulate the browser auto-refocus of the input
  fireEvent.focus(calendarInput);
};

describe("DatePicker", () => {
  beforeEach(() => {
    setupMockResizeObserver();
  });

  afterEach(() => {
    jest.resetAllMocks();
  });

  it("exposes locale helpers via the main entry point", () => {
    const originalLocale = getDefaultLocale();
    try {
      expect(getDefaultLocale()).toBe(originalLocale);
      setDefaultLocale("en-GB");
      expect(getDefaultLocale()).toBe("en-GB");
    } finally {
      setDefaultLocale(originalLocale);
    }
  });

  it("does not trigger selection changes when readOnly", () => {
    const onChange = jest.fn();
    const { instance } = renderDatePickerWithRef({
      readOnly: true,
      onChange,
    });

    act(() => {
      instance?.handleSelect(newDate("2024-05-01"));
    });

    expect(onChange).not.toHaveBeenCalled();
  });

  it("skips updating preSelection when readOnly", () => {
    const selected = newDate("2024-01-01");
    const { instance } = renderDatePickerWithRef({
      readOnly: true,
      selected,
    });

    const originalPreSelection = instance?.state.preSelection;

    act(() => {
      instance?.setPreSelection(newDate("2024-02-01"));
    });

    expect(instance?.state.preSelection).toBe(originalPreSelection);
  });

  it("short-circuits day key navigation when keyboard navigation is disabled", () => {
    const onKeyDown = jest.fn();
    const preSelection = newDate("2024-06-15");
    const { instance } = renderDatePickerWithRef({
      disabledKeyboardNavigation: true,
      onKeyDown,
      inline: true,
      selected: preSelection,
    });

    act(() => {
      instance?.setState({ preSelection });
    });

    act(() => {
      instance?.onDayKeyDown({
        key: "ArrowRight",
        shiftKey: false,
        preventDefault: jest.fn(),
      } as unknown as React.KeyboardEvent<HTMLDivElement>);
    });

    expect(onKeyDown).toHaveBeenCalled();
    expect(instance?.state.preSelection).toBe(preSelection);
  });

  it("should retain the calendar open status when the document visibility change", () => {
    const { container } = render(<DatePicker />);
    const input = safeQuerySelector(container, "input");

    if (!input) {
      throw new Error("Input element not found");
    }

    fireEvent.click(input);
    expect(container.querySelector(".react-datepicker")).toBeTruthy();

    hideDocument(input);
    showDocument(input);

    expect(container.querySelector(".react-datepicker")).toBeTruthy();
  });

  it("should retain the calendar close status when the document visibility change", () => {
    const { container } = render(<DatePicker />);
    const input = safeQuerySelector(container, "input");
    fireEvent.click(input);
    expect(container.querySelector(".react-datepicker")).toBeTruthy();

    fireEvent.keyDown(input, getKey(KeyType.Escape));
    expect(container.querySelector(".react-datepicker")).toBeFalsy();

    hideDocument(input);
    showDocument(input);

    expect(container.querySelector(".react-datepicker")).toBeFalsy();
  });

  it("should be executed props.onFocus on input focus when the document visibility changes", () => {
    const onFocusSpy = jest.fn();

    const { container } = render(<DatePicker onFocus={onFocusSpy} />);

    const input = safeQuerySelector<HTMLInputElement>(container, "input");

    fireEvent.focus(input);
    expect(onFocusSpy).toHaveBeenCalled();

    expect(container.querySelector(".react-datepicker")).toBeTruthy();
    fireEvent.keyDown(input, getKey(KeyType.Escape));
    fireEvent.blur(input);
    expect(container.querySelector(".react-datepicker")).toBeFalsy();

    hideDocument(input);
    showDocument(input);

    expect(onFocusSpy).toHaveBeenCalled();
    expect(container.querySelector(".react-datepicker")).toBeFalsy();

    fireEvent.click(input);
    expect(onFocusSpy).toHaveBeenCalled();
    expect(container.querySelector(".react-datepicker")).toBeTruthy();
  });

  it("should show the calendar when focusing on the date input", () => {
    const { container } = render(<DatePicker />);

    const input = safeQuerySelector<HTMLInputElement>(container, "input");
    fireEvent.focus(input);
    expect(container.querySelector(".react-datepicker")).not.toBeNull();
  });

